sp_widget.client_script:
api.controller = function($scope,$element) {
  var c = this;

  // Initialize flip state
  $scope.isFlipped = false;

  // Function to toggle the flip effect
  $scope.toggleFlip = function() {
    $scope.isFlipped = !$scope.isFlipped;

  };


	//This is a test

  // Cycle directions based on index


	  // Cycle directions based on index
  $scope.getScrollAnimationClass = function(index) {
    var directions = ['slide-in-left', 'slide-in-right', 'slide-in-top', 'slide-in-bottom'];
    return directions[index % directions.length];
  };

  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add('show');
        observer.unobserve(entry.target); // animate only once
      }
    });
  });

  // Wait for DOM rendering
  setTimeout(function() {
    var elements = $element[0].querySelectorAll('.animate-hidden');
    Array.prototype.forEach.call(elements, function(el) {
      observer.observe(el);
    });
  }, 0);






};

sp_widget.css:
.dip {
  perspective: 1000px;
}
.s-icon{
  width:100px;
  height:100px;
}
.flip-container {
 
  height: 280px; /* Adjust as needed */
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.6s;

  border-radius:10px;
  border:3px solid #dee2e6;

}

body{
 overflow-X: hidden;
}

.flip-container:hover {

    box-shadow: 2px 2px 6px 3px grey;
  transform: scale(1.05);
  border:1px solid #f2a900;
}
.front{

}

.g-box h6{
  font-size:19px;
  font-weight:700;
}

.front, .back {
  position: absolute;
  color: white;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  border-radius:10px;
  background: #FEA648;
}

.front {
  background: #FEA648; /* Adjust as needed */
}
h6{
  font-family: times new roman;
}

.back {
 

  display: flex;
  flex-direction:column;
  align-items: center;
  justify-content: center;
  transform: rotateY(180deg);
  padding:10px;
  
}
.back  p{
  font-size:12px;
  font-weight:600;
  font-family: times new roman;
}

.flipped .flip-container {
  transform: rotateY(180deg);
}

.g-box{
  display:flex;
  flex-direction:column;
  align-items:center;
  padding:20px
}
.btn-div{
  position: absolute;
  width: 700px;
  height: 250px;
}
.reqBtn{
  position: relative;
  width:80px;
  height:35px;
  display:flex;
  justify-content:center;
  align-items:center;
  background-color:#f2a900;
  color:white;
  font-weight:600;
  border-radius:3px;
  font-size:13px;
  transition:all 0.4s;
  right: -380px;
  bottom: -200px;
  font-family: times new roman;
  
}

.reqBtn:hover {
  background-color: #f6bb5b;
}
.reqBtn:active{
  transform: translateY(2px);
  box-shadow: 2px 2px 0px 0px rgb(37, 36, 36);
}


.main-box{
  padding-top:15px;
  padding-bottom:25px;
}

.p-short{
  text-align:center;
  font-family: times new roman;
}
.back-text{
  font-size: 18px;
  font-family: times new roman;
}
//////////////////////////////////////////////////////

/* General hidden state */
.animate-hidden {
  opacity: 0;
  transition: all 1.2s ease-out; 
}

/* Animate in from left */
.slide-in-left {
  transform: translateX(-100%);
}

.slide-in-left.show {
  opacity: 1;
  transform: translateX(0);
}

/* Animate in from right */
.slide-in-right {
  transform: translateX(100%);
}

.slide-in-right.show {
  opacity: 1;
  transform: translateX(0);
}

/* Animate in from top */
.slide-in-top {
  transform: translateY(-100%);
}

.slide-in-top.show {
  opacity: 1;
  transform: translateY(0);
}


/* Slide in from bottom */
.slide-in-bottom {
  transform: translateY(100%);
}

.slide-in-bottom.show {
  opacity: 1;
  transform: translateY(0);
}

